<section id="contact" class="py-12">
  <h2 class="text-2xl font-mecha mb-4" style="color: var(--eva-green);">Contacto</h2>
  <form action="https://formspree.io/f/your-form-id" method="POST" class="space-y-4 max-w-md mx-auto rounded-lg p-6 shadow-lg" style="background-color: #181825; border: 1px solid var(--eva-green);">
    <input type="text" name="name" placeholder="Nombre" required class="w-full px-3 py-2 rounded" style="background-color: #181825; border: 1px solid var(--eva-green); color: var(--eva-green);" />
    <input type="email" name="email" placeholder="Email" required class="w-full px-3 py-2 rounded" style="background-color: #181825; border: 1px solid var(--eva-green); color: var(--eva-green);" />
    <textarea name="message" placeholder="Mensaje" required class="w-full px-3 py-2 rounded" style="background-color: #181825; border: 1px solid var(--eva-green); color: var(--eva-green);"></textarea>
    <button type="submit" class="btn-eva w-full">Enviar</button>
  </form>
  <div class="flex justify-center gap-4 mt-6">
    <a href="https://github.com/tuusuario" target="_blank" class="text-2xl" style="color: var(--eva-accent);" aria-label="GitHub"><i class="fab fa-github"></i>GitHub</a>
    <a href="https://linkedin.com/in/tuusuario" target="_blank" class="text-2xl" style="color: var(--eva-accent);" aria-label="LinkedIn"><i class="fab fa-linkedin"></i>LinkedIn</a>
    <a href="mailto:tu@email.com" class="text-2xl" style="color: var(--eva-accent);" aria-label="Email"><i class="fas fa-envelope"></i>Email</a>
  </div>
</section>
